native_configs.Caddyfile:
{
	admin off
	auto_https off
}
http://127.0.0.1:18281 {
	reverse_proxy 127.0.0.1:19201 {
		transport fastcgi {
			root {$ZERNO_ROOT}/public
			env SCRIPT_FILENAME {$ZERNO_ROOT}/public/http.php
			env SCRIPT_NAME /http.php
		}
	}
}
http://127.0.0.1:18282 {
	reverse_proxy 127.0.0.1:19202
}
